/* @ts-nocheck */
import React, { useRef, useState } from 'react';
import { useThemeClasses } from '../shared/use-theme-classes.js';
import { useDarkClasses } from '../shared/use-dark-classes.js';
import { MessagebarClasses } from '../../shared/classes/MessagebarClasses.js';
import { MessagebarColors } from '../../shared/colors/MessagebarColors.js';
import Toolbar from './Toolbar.tsx';
import Glass from './Glass.tsx';

const Messagebar = (props) => {
  const {
    component = 'div',
    className,
    colors: colorsProp,
    id,
    style,
    name,
    placeholder = 'Message',
    value,
    outline = false,
    // eslint-disable-next-line
    leftClassName = '',
    // eslint-disable-next-line
    rightClassName = '',
    textareaId,
    disabled,
    size,

    left,
    right,

    ios,
    material,

    onInput,
    onChange,
    onFocus,

    children,
    ref,

    ...rest
  } = props;

  const elRef = useRef(null);
  const areaElRef = useRef(null);

  const [isFocused, setIsFocused] = useState(false);

  const themeClasses = useThemeClasses({ ios, material });
  const dark = useDarkClasses();

  const colors = MessagebarColors(colorsProp, dark);

  const onFocusInternal = (e) => {
    setIsFocused(true);
    if (onFocus) onFocus(e);
  };

  const c = themeClasses(
    MessagebarClasses(
      { ...props },
      colors,
      {
        isFocused,
      },
      className
    )
  );

  const Component = component;

  const attrs = {
    ...rest,
  };

  return (
    <Component
      ref={(el) => {
        elRef.current = el;
        if (ref && typeof ref === 'function') ref(el);
        else if (ref) ref.current = el;
      }}
      id={id}
      style={style}
      className={c.base}
      {...attrs}
    >
      <Toolbar
        colors={colors}
        outline={outline}
        className={c.toolbar}
        innerClassName={c.toolbarInner}
      >
        {left && <div className={c.left}>{left}</div>}
        <Glass className={c.messagebarArea}>
          <textarea
            id={textareaId}
            ref={areaElRef}
            type="textarea"
            className={c.messagebarInput}
            placeholder={placeholder}
            name={name}
            size={size}
            disabled={disabled}
            onInput={onInput}
            onChange={onChange}
            onFocus={onFocusInternal}
            value={value}
          />
        </Glass>
        {right && <div className={c.right}>{right}</div>}
      </Toolbar>
    </Component>
  );
};

Messagebar.displayName = 'Messagebar';
export default Messagebar;

/* @ts-nocheck */
import React, { useEffect, useRef, useContext } from 'react';
import { GlassClasses } from '../../shared/classes/GlassClasses.js';
import { GlassColors } from '../../shared/colors/GlassColors.js';
import { useThemeClasses } from '../shared/use-theme-classes.js';
import { useTheme } from '../shared/use-theme.js';
import { useDarkClasses } from '../shared/use-dark-classes.js';
import { useIosHighlight } from '../../shared/use-ios-highlight.js';
import { CapacitorContext } from '../shared/CapacitorContext.js';

const Glass = (props) => {
  const {
    component = 'div',
    colors: colorsProp,
    className,
    highlight = true,

    ios,
    material,

    // Children
    children,

    ref,

    // Rest
    ...rest
  } = props;

  const elRef = useRef(null);

  const Component = component;

  const attrs = {
    ...rest,
  };

  const theme = useTheme();

  const themeClasses = useThemeClasses({ ios, material });
  const dark = useDarkClasses();

  const colors = GlassColors(colorsProp, dark);

  const { touchHighlight } = useContext(CapacitorContext);

  const highlightData = useRef({});
  const { attachEvents, detachEvents } = useIosHighlight({
    getEl: () => elRef.current,
    enabled: highlight && theme === 'ios' && touchHighlight,
    data: highlightData.current,
  });

  const c = themeClasses(GlassClasses(props, colors), className);

  useEffect(() => {
    attachEvents();
    return () => detachEvents();
  });

  return (
    <Component
      ref={(el) => {
        if (ref && typeof ref === 'function') ref(el);
        else if (ref) ref.current = el;
        elRef.current = el;
      }}
      className={c.base}
      {...attrs}
    >
      {children}
    </Component>
  );
};

Glass.displayName = 'Glass';

export default Glass;
